        ConsentConfigurationEntity consentConfiguration = consentConfigurationService.getByConsentTemplateId(
                consentsRequestFromFIU.getConsentTemplateId(),
                consentInitEntity.getConsentDetail().getDataConsumer().getId());

        ConsentDetail consentDetail = buildConsentDetailByConsentTemplate(
                consentConfiguration.getConsentConfigurationRequest());

