        for line in r.stdout.splitlines():
            if line.startswith("Compiled from"):
                if cur is not None: out[cur]="\n".join(buf)
                cur=line; buf=[]
            else:
                buf.append(line)
        if cur is not None: out[cur]="\n".join(buf)
